import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-07","description":"2026-09-07 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-07","description":"2026-09-07 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-07.md","filePath":"zh/runtime/daily-intelligence/2026-09-07.md","lastUpdated":1788922160000}'),a={name:"zh/runtime/daily-intelligence/2026-09-07.md"};function i(s,e,p,l,c,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-核心研究与竞品动态-·-2026-09-07" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-07 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-07" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-07&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 仅收录达到 meaningful new developments 阈值的公开技术与产品变化。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>本日最强的共振是：<strong>Agent Runtime 正把“最后一次安全检查”不断推近真实副作用边界，同时把能力声明、执行所有权和操作语义从模糊标签变成可验证合同。</strong></p><h2 id="_1-openai-codex-单写者会话、windows-受管进程控制与-human-verification" tabindex="-1">1. OpenAI Codex：单写者会话、Windows 受管进程控制与 Human Verification <a class="header-anchor" href="#_1-openai-codex-单写者会话、windows-受管进程控制与-human-verification" aria-label="Permalink to &quot;1. OpenAI Codex：单写者会话、Windows 受管进程控制与 Human Verification&quot;">​</a></h2><p><strong>状态：MERGED / MERGED / MERGED（能力仍受 gate）</strong></p><p>Codex 连续收紧三条执行控制边界：</p><ul><li>PR <a href="https://github.com/openai/codex/pull/43253" target="_blank" rel="noreferrer">#43253</a>：当已有实例持有 conversation active writer 时，新 resume 不再抢写，而是降级为 read-only history snapshot；原 writer 关闭后才允许显式重试。这形成了清晰的 <strong>single-writer lease / multi-reader observation</strong> 模型。</li><li>PR <a href="https://github.com/openai/codex/pull/43308" target="_blank" rel="noreferrer">#43308</a>：Windows managed app-server 的 shutdown 改为本地 control socket <code>/daemon/shutdown</code>，请求必须绑定并匹配 Server PID；先 ACK，再进入 drain，PID 不匹配或非 managed launch 会拒绝。</li><li>PR <a href="https://github.com/openai/codex/pull/43289" target="_blank" rel="noreferrer">#43289</a>：加入 MCP <code>openai/userVerification</code> 协议处理，只有 client 明确声明 capability 才接受；proof 有格式、大小、取消和容量限制。当前 Codex 仍未全面激活这一能力。</li></ul><p><strong>为什么重要：</strong> Conversation ownership、Process control、Human verification 都在从“当前状态”变成 capability-gated、identity-bound 的控制对象。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Runtime 状态不能只写 <code>Running</code>，还需要区分 <strong>Writer Lease / Observer Access / Host Process Identity / Human Verification Receipt</strong>。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Will user-verification proofs eventually be bound to the active writer/authority epoch, so a proof obtained by one conversation owner cannot survive a writer handoff?</em></p><h2 id="_2-openai-agents-sdk-工具名字并不是副作用合同" tabindex="-1">2. OpenAI Agents SDK：工具名字并不是副作用合同 <a class="header-anchor" href="#_2-openai-agents-sdk-工具名字并不是副作用合同" aria-label="Permalink to &quot;2. OpenAI Agents SDK：工具名字并不是副作用合同&quot;">​</a></h2><p><strong>状态：OPEN / OPEN</strong></p><p>两个新问题都说明，仅凭 tool name 无法推断真实 effect：</p><ul><li>PR <a href="https://github.com/openai/openai-agents-python/pull/4893" target="_blank" rel="noreferrer">#4893</a>：<code>apply_patch</code> 的 <code>*** Add File:</code> 在目标文件已存在时可能静默覆盖，并仍向模型报告 <code>Created</code>。候选修复要求 create 必须证明 destination 不存在，否则明确拒绝。</li><li>PR <a href="https://github.com/openai/openai-agents-python/pull/4894" target="_blank" rel="noreferrer">#4894</a>：sandbox S3 mount 通过逗号拼接 mount options，某些字段值可借 delimiter 注入额外 mount option。候选修复要求在进入 <code>mount -o</code> 的 key/value 上拒绝这种语法层能力扩张。</li></ul><p><strong>为什么重要：</strong> <code>create</code> 不能实际是 upsert；一个配置字段也不能偷偷展开成第二种 capability。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 授权判断应该基于 <strong>normalized effect semantics</strong>，而不是基于工具名或 UI 标签。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Would you expose normalized effect classes from sandbox tools, so authorization can distinguish create-only, overwrite and mount-policy mutation without reverse-engineering arguments?</em></p><h2 id="_3-ag2-mcp-apps-引入-app-可调用、模型不可见-的工具主体" tabindex="-1">3. AG2：MCP Apps 引入“App 可调用、模型不可见”的工具主体 <a class="header-anchor" href="#_3-ag2-mcp-apps-引入-app-可调用、模型不可见-的工具主体" aria-label="Permalink to &quot;3. AG2：MCP Apps 引入“App 可调用、模型不可见”的工具主体&quot;">​</a></h2><p><strong>状态：OPEN</strong></p><p>PR <a href="https://github.com/ag2ai/ag2/pull/3235" target="_blank" rel="noreferrer">#3235</a> 为 AG2 Agent Server 加入 MCP Apps (<code>io.modelcontextprotocol/ui</code>) 支持。UI document 作为 Resource 与 Tool 绑定，支持 <code>structuredContent</code>、SEP-2133 extension negotiation，以及 AppResource 的 CSP / permissions / domain 等 sandbox policy。</p><p>最值得关注的是 <code>visibility=[&quot;app&quot;]</code>：某些工具可由 MCP App 中的按钮调用，但不会暴露给模型。</p><p><strong>为什么重要：</strong> MCP 的执行主体从单一的 <code>Model → Tool</code> 扩展为至少两条路径：<code>Model → Tool</code> 与 <code>Human → App UI → Tool</code>。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 数字员工面板里的批准、执行、重试、撤回按钮，都应被视为正式 invocation principal，而不是 UI 绕过协议直接改状态。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>For app-only tools, do you plan to expose distinct invocation-principal / user-gesture provenance so audit can distinguish model-selected calls from human UI actions?</em></p><h2 id="_4-paperclip-pre-start-admission、插件能力升级与恢复事故" tabindex="-1">4. Paperclip：Pre-start Admission、插件能力升级与恢复事故 <a class="header-anchor" href="#_4-paperclip-pre-start-admission、插件能力升级与恢复事故" aria-label="Permalink to &quot;4. Paperclip：Pre-start Admission、插件能力升级与恢复事故&quot;">​</a></h2><p><strong>状态：OPEN / OPEN / OPEN</strong></p><p>Paperclip 本日继续逼近治理 Runtime：</p><ul><li>PR <a href="https://github.com/paperclipai/paperclip/pull/12949" target="_blank" rel="noreferrer">#12949</a>：增加 provider 副作用之前的 <strong>pre-start admission hook</strong>。Run 已 claim、但 adapter/native runner/provider 尚未启动时，Host 可基于 issue、run、wake、provider、model、capacity snapshot 做最后裁决；Enforce 模式下 telemetry 缺失、过期或无效会 fail closed，veto 后保证零 provider call。</li><li>PR <a href="https://github.com/paperclipai/paperclip/pull/12928" target="_blank" rel="noreferrer">#12928</a>：处理 Plugin capability escalation。升级新增 capability 不再自动扩大 grant，而进入 <code>upgrade_pending</code>，需要 operator 明确批准；同时增加 manifest drift 检测。</li><li>PR <a href="https://github.com/paperclipai/paperclip/pull/12946" target="_blank" rel="noreferrer">#12946</a>：汇总并修复环境 lease 释放后 Agent 永远 Running、continuation retry cap 被错误码交替绕过、API abort 却 exit 0、cross-issue guard 使用错误证据等真实运行问题。</li></ul><p><strong>为什么重要：</strong> Paperclip 正形成 <code>Declared Capability → Approved Grant → Pre-start Admission → Run Ownership → Provider Effect → Recovery Classification</code> 的治理链。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 与 Host 准入、call-time authorization、恢复治理直接重合。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：维持一线 Runtime 竞品。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Will pre-start admission be bound to an authority epoch/effect receipt so a queued run cannot execute after telemetry or capability grants materially change?</em></p><h2 id="_5-github-mcp-server-精确补丁工具拒绝-fuzzy-write" tabindex="-1">5. GitHub MCP Server：精确补丁工具拒绝 fuzzy write <a class="header-anchor" href="#_5-github-mcp-server-精确补丁工具拒绝-fuzzy-write" aria-label="Permalink to &quot;5. GitHub MCP Server：精确补丁工具拒绝 fuzzy write&quot;">​</a></h2><p><strong>状态：DRAFT</strong></p><p>Draft PR <a href="https://github.com/github/github-mcp-server/pull/3232" target="_blank" rel="noreferrer">#3232</a> 新增 <code>apply_file_patch</code>。背景是一份约 303 KB changelog 的修改中，完整 replacement 在上游被截断，错误 commit 虽被拦截，但恢复需要借助本地 Git client。</p><p>新工具要求同时提供 exact <code>expected_head_sha</code> 与 exact <code>expected_blob_sha</code>，且 <code>old_text</code> 必须精确出现预期次数；禁止 fuzzy matching、offset guessing、no-op、symlink、非 UTF-8 和过大 patch。最终 branch update 使用 <code>force=false</code>，并发变更会 non-fast-forward 失败，而不是覆盖别人的新事实。</p><p><strong>为什么重要：</strong> 写操作开始携带明确的 effect preconditions：只有“我预期的 Branch 和 File 仍然成立”时才允许执行。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 与并发线性化、幂等、原子更新、effect precondition 高度一致。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Would you return a durable effect receipt containing expected head/blob and resulting commit/blob, making the precondition-to-effect transition directly auditable?</em></p><h2 id="_6-orca-unknown-只能被正证据收敛-不能被-timeout-猜成事实" tabindex="-1">6. Orca：Unknown 只能被正证据收敛，不能被 timeout 猜成事实 <a class="header-anchor" href="#_6-orca-unknown-只能被正证据收敛-不能被-timeout-猜成事实" aria-label="Permalink to &quot;6. Orca：Unknown 只能被正证据收敛，不能被 timeout 猜成事实&quot;">​</a></h2><p><strong>状态：MERGED / OPEN / OPEN</strong></p><ul><li>PR <a href="https://github.com/stablyai/orca/pull/19140" target="_blank" rel="noreferrer">#19140</a> 已合入：Structured Claude Chat 的一条 submission 若先被标记为 <code>unknown</code>，但后续 provider echo 能证明该消息实际已接受，则 durable journal 会由 <code>unknown → accepted</code>，且<strong>不产生第二次 dispatch</strong>。</li><li>PR <a href="https://github.com/stablyai/orca/pull/19149" target="_blank" rel="noreferrer">#19149</a>：处理 Windows PID reuse，新增 PID creation-time ordering 作为 ancestry evidence；证据不足仍保持 <code>unverifiable</code>。</li><li>PR <a href="https://github.com/stablyai/orca/pull/19155" target="_blank" rel="noreferrer">#19155</a>：provider root 已正证明死亡且无 known-live descendant 时，可释放 native session lease，同时保留 uncertain descendant-cleanup evidence；<strong>lease expiry 本身不能证明 owner 已死</strong>。</li></ul><p><strong>为什么重要：</strong> Unknown 可以被后续正证据收敛，但 timeout、lease expiry、PID 数值都不能自行升级成事实。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Recovery 与 lifecycle state 应采用 evidence-driven settlement，而不是 <code>if timeout then dead</code> 的二态推断。</p><p><strong>学习：非常高｜竞争风险：中高｜雷达判断：提高 Orca 的 long-running / Windows / recovery 权重。</strong></p><p><strong>值得互动：高。</strong> 技术切入：<em>Do you plan to converge delivery and process/lease evidence onto one general transition model where <code>unknown → accepted/dead</code> requires a named positive observation?</em></p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><p>本日可以归纳成一条非常强的原则：</p><blockquote><p><strong>真正安全的 Agent 不是“先判断一次，然后长期相信”，而是在距离副作用越来越近的地方不断重新证明：对象还是那个对象、能力还是那份能力、Owner 还是那个 Owner、前置事实还成立。</strong></p></blockquote><p>对 CodeFlowMu/FCoP，建议把执行链继续明确为：</p><p><strong>Capability Grant → Admission Decision → Effect Preconditions → Call-time Authority → Effect Receipt → Evidence-driven Settlement</strong>。</p><p>其中任何一环都不应由“上一次检查通过”自动替代下一环。</p><h2 id="双源核查说明" tabindex="-1">双源核查说明 <a class="header-anchor" href="#双源核查说明" aria-label="Permalink to &quot;双源核查说明&quot;">​</a></h2><p>本日同时检查公开社交/项目官方源与 GitHub 一手变更。没有发现 41 位人物中身份可可靠确认、发布时间足够新且技术增量高于上述 GitHub 一手变化的本人新讨论，因此未使用营销转发或疑似账号补数。</p>',56)])])}const h=o(a,[["render",i]]);export{g as __pageData,h as default};
